h2_transport_read:
// Always try TLS-buffered data before the first idle wait. After a benign
// timeout, socket readiness or a queued writer wake triggers the next attempt.
// The retained wake keeps its descriptors alive if close races with poll.
fn (mut t H2PooledTransport) read(mut buf []u8) !int {
    t.vox_lock_io()
    if t.closed {
        t.io_mu.unlock()
        return error('h2 pooled transport: closed')
    }
    if t.vox_wait_before_read && t.vox_wake != unsafe { nil } {
        wake := C.vox_h2_wake_retain(t.vox_wake)
        socket := t.conn.handle
        t.io_mu.unlock()
        ready := C.vox_h2_wake_wait(wake, i32(socket), 500)
        if ready == 0 { return error_with_code('h2 pooled transport: idle timeout', net.err_timed_out_code) }
        if ready < 0 { return error('h2 pooled transport: idle wait closed or failed') }
        t.vox_lock_io()
        if t.closed {
            t.io_mu.unlock()
            return error('h2 pooled transport: closed')
        }
    }
    n := t.conn.read(mut buf) or {
        // mbedTLS reports its short read deadline as MBEDTLS_ERR_SSL_TIMEOUT,
        // not net.err_timed_out_code. Any benign timeout must enter the idle
        // wait; otherwise an idle connection polls TLS every 5 ms forever.
        t.vox_wait_before_read = err.code() == net.err_timed_out_code
            || is_transport_timeout_error(err)
        t.io_mu.unlock()
        return err
    }
    t.vox_wait_before_read = false
    t.io_mu.unlock()
    return n
}

h2_window_updates:
fn (mut c H2MuxConn) send_window_updates(stream_id u32, n u32) ! {
    if n == 0 { return }
    // A consumer need not write credit for every small DATA chunk. Keep
    // consumed credit until about half a window has been consumed.
    // Low remaining windows force a flush independently at
    // each level, so many small concurrent streams cannot exhaust the shared
    // connection window while waiting for their individual thresholds.
    threshold := u32(h2_default_initial_window / 2)
    mut stream_increment := u32(0)
    mut force_credit := true
    c.smu.lock()
    if mut s := c.streams[stream_id] {
        s.mu.lock()
        force_credit = s.vox_force_recv_credit || s.err != '' || s.cancelled
        s.vox_pending_recv_credit += n
        if s.ended && !force_credit {
            // A normally completed stream will receive no more DATA. Keep
            // its connection credit, but discard the unnecessary stream ACK.
            s.vox_pending_recv_credit = 0
        } else if force_credit || s.recv_window <= i64(threshold)
            || s.vox_pending_recv_credit >= threshold {
            stream_increment = s.vox_pending_recv_credit
            s.vox_pending_recv_credit = 0
            s.recv_window += i64(stream_increment)
        }
        s.mu.unlock()
    }
    c.smu.unlock()
    mut connection_increment := u32(0)
    c.recv_wmu.lock()
    c.vox_pending_conn_credit += n
    if force_credit || c.conn_recv_window <= i64(threshold)
        || c.vox_pending_conn_credit >= threshold {
        connection_increment = c.vox_pending_conn_credit
        c.vox_pending_conn_credit = 0
        c.conn_recv_window += i64(connection_increment)
    }
    c.recv_wmu.unlock()
    if connection_increment == 0 && stream_increment == 0 { return }
    mut buf := []u8{}
    if connection_increment > 0 {
        buf << H2Frame(H2WindowUpdateFrame{
            stream_id: 0
            window_size_increment: connection_increment
        }).encode()
    }
    if stream_increment > 0 {
        buf << H2Frame(H2WindowUpdateFrame{
            stream_id: stream_id
            window_size_increment: stream_increment
        }).encode()
    }
    c.wmu.lock()
    c.write_all_locked(buf) or {
        c.wmu.unlock()
        c.note_write_failure()
        return err
    }
    c.wmu.unlock()
}

h2_read_chunk_old:
for c.rbuf.len < n {
	mut tmp := []u8{len: h2_conn_read_chunk}
	got := c.transport.read(mut tmp)!
	if got <= 0 {
		return error('connection closed by peer')
	}
	c.rbuf << tmp[..got]
}

